le":"standard","category":"messages","text":"Bits could've beat HAL","weight":1,"colorful":false,"format":{},"enabled":true},{"position":681,"profile":"standard","category":"messages","text":"Bits are the true masters of the universe","weight":1,"colorful":false,"format":{},"enabled":true},{"position":682,"profile":"standard","category":"messages","text":"Bits in the Matrix","weight":1,"colorful":false,"format":{},"enabled":true},{"position":683,"profile":"standard","category":"messages","text":"Bits in the multiverse","weight":1,"colorful":false,"format":{},"enabled":true},{"position":684,"profile":"standard","category":"messages","text":"Bits in the quantum realm","weight":1,"colorful":false,"format":{},"enabled":true},{"position":685,"profile":"standard","category":"messages","text":"Bits in the digital ether","weight":1,"colorful":false,"format":{},"enabled":true},{"position":686,"profile":"standard","category":"messages","text":"Bits in the cloud","weight":1,"colorful":false,"format":{},"enabled":true},{"position":687,"profile":"standard","category":"messages","text":"Bits in the blockchain","weight":1,"colorful":false,"format":{},"enabled":true},{"position":688,"profile":"standard","category":"messages","text":"Bits in the metaverse","weight":1,"colorful":false,"format":{},"enabled":true},{"position":689,"profile":"standard","category":"messages","text":"Bits in the simulation","weight":1,"colorful":false,"format":{},"enabled":true},{"position":690,"profile":"standard","category":"messages","text":"MAGA is dumb","weight":1,"colorful":false,"format":{},"enabled":true},{"position":691,"profile":"standard","category":"messages","text":"Things are not often blue or red, but rather very purple","weight":1,"colorful":false,"format":{},"enabled":true},{"position":692,"profile":"standard","category":"messages","text":"Vote for the lesser of two evils","weight":1,"colorful":false,"format":{},"enabled":true},{"position":693,"profile":"standard","category":"messages","text":"He told you he would do this","weight":1,"colorful":false,"format":{},"enabled":true},{"position":694,"profile":"standard","category":"messages","text":"The future is uncertain, but bits persist","weight":1,"colorful":false,"format":{},"enabled":true},{"position":695,"profile":"standard","category":"messages","text":"Bits will inherit the earth","weight":1,"colorful":false,"format":{},"enabled":true},{"position":696,"profile":"standard","category":"messages","text":"Bits are the future","weight":1,"colorful":false,"format":{},"enabled":true},{"position":697,"profile":"standard","category":"messages","text":"Bits will shape tomorrow","weight":1,"colorful":false,"format":{},"enabled":true},{"position":698,"profile":"standard","category":"messages","text":"Nothing in life is gauranteed besides Death, Taxes, and Bits","weight":1,"colorful":false,"format":{},"enabled":true},{"position":699,"profile":"standard","category":"messages","text":"Bits are eternal","weight":1,"colorful":false,"format":{},"enabled":true},{"position":700,"profile":"standard","category":"messages","text":"Bits transcend time and space","weight":1,"colorful":false,"format":{},"enabled":true},{"position":701,"profile":"standard","category":"messages","text":"There are two kinds of people on the planet: those who make it better, and those who make it better when they leave","weight":1,"colorful":false,"format":{},"enabled":true},{"position":702,"profile":"standard","category":"messages","text":"Some people cherish every minute, every hour. Some try to build giant towers to live beyound the grave","weight":1,"colorful":false,"format":{},"enabled":true},{"position":703,"profile":"standard","category":"messages","text":"Some people find meaning in spreading love around. Some people find meaning in keeping other people down. Some people have a real hard time when other people claim that some people think those two things can be the same","weight":1,"colorful":false,"format":{},"enabled":true},{"position":704,"profile":"standard","category":"messages","text":"Some stay to fight a problem til it's better than it was. Some people pack their things and move along once they've had enough","weight":1,"colorful":false,"format":{},"enabled":true},{"position":705,"profile":"standard","category":"messages","text":"Sometimes we know just what to do but no one wants to do it","weight":1,"colorful":false,"format":{},"enabled":true},{"position":706,"profile":"standard","category":"messages","text":"There are sides that you can join and they'll tell you just what to say and think.","weight":1,"colorful":false,"format":{},"enabled":true},{"position":707,"profile":"standard","category":"messages","text":"Sometimes the loudest voices are the ones that know the least","weight":1,"colorful":false,"format":{},"enabled":true},{"position":708,"profile":"standard","category":"messages","text":"Wisdom often comes from the quietest corners","weight":1,"colorful":false,"format":{},"enabled":true},{"position":709,"profile":"standard","category":"messages","text":"Patience is a virtue often overlooked","weight":1,"colorful":false,"format":{},"enabled":true},{"position":710,"profile":"standard","category":"messages","text":"Courage is not the absence of fear, but the triumph over it","weight":1,"colorful":false,"format":{},"enabled":true},{"position":711,"profile":"standard","category":"messages","text":"True strength is often found in the quietest moments","weight":1,"colorful":false,"format":{},"enabled":true},{"position":712,"profile":"standard","category":"messages","text":"Every \"freedom\" has its price","weight":1,"colorful":false,"format":{},"enabled":true},{"position":713,"profile":"standard","category":"messages","text":"Knowledge is knowing a tomato is a fruit; wisdom is not putting it in a fruit salad","weight":1,"colorful":false,"format":{},"enabled":true},{"position":714,"profile":"standard","category":"messages","text":"The journey of a thousand miles begins with a single step","weight":1,"colorful":false,"format":{},"enabled":true},{"position":715,"profile":"standard","category":"messages","text":"Do not go where the path may lead, go instead where there is no path and leave a trail","weight":1,"colorful":false,"format":{},"enabled":true},{"position":716,"profile":"standard","category":"messages","text":"In the middle of difficulty lies opportunity","weight":1,"colorful":false,"format":{},"enabled":true},{"position":717,"profile":"standard","category":"messages","text":"Do not wait to strike till the iron is hot; but make it hot by striking","weight":1,"colorful":false,"format":{},"enabled":true},{"position":718,"profile":"standard","category":"messages","text":"Great minds discuss ideas; average minds discuss events; small minds discuss people","weight":1,"colorful":false,"format":{},"enabled":true},{"position":719,"profile":"standard","category":"messages","text":"The best way to predict the future is to invent it","weight":1,"colorful":false,"format":{},"enabled":true},{"position":720,"profile":"standard","category":"messages","text":"I should really pay for MakeMKV","weight":1,"colorful":false,"format":{},"enabled":true},{"position":721,"profile":"standard","category":"messages","text":"I should really clean my desk","weight":1,"colorful":false,"format":{},"enabled":true},{"position":722,"profile":"standard","category":"messages","text":"I should really organize my files","weight":1,"colorful":false,"format":{},"enabled":true},{"position":723,"profile":"standard","category":"messages","text":"I should really update my software","weight":1,"colorful":false,"format":{},"enabled":true},{"position":724,"profile":"standard","category":"messages","text":"I should really back up my data","weight":1,"colorful":false,"format":{},"enabled":true},{"position":725,"profile":"standard","category":"messages","text":"I should really declutter my inbox","weight":1,"colorful":false,"format":{},"enabled":true},{"position":726,"profile":"standard","ca